"use strict";
const assert=require("node:assert/strict");
const crypto=require("node:crypto");
const {RULESET_VERSION,MEDIA_TYPE,OUTCOMES,canonicalStringify,createBootstrapApprovalPresentationCapture}=require("./bootstrap-approval-presentation-capture");
const payload={type:"GT63_BOOTSTRAP_APPROVAL",decision:"APPROVE",governanceAct:"INITIAL_GOVERNANCE_BOOTSTRAP",bootstrapGateId:"gate:1",bootstrapGateRevision:"1",repositoryIdentity:"goceterziev-creator/2l1p-neural-travel-v9",targetPath:"config/gt63-machine/governance-lifecycle-issuer-scope-policy-v0.json",beforeStateId:"sha256:before",afterStateId:"sha256:after",oneTime:true};
const bytes=Buffer.from(`${canonicalStringify(payload)}\n`,"utf8");const sha256=b=>`sha256:${crypto.createHash("sha256").update(b).digest("hex")}`;
function ledger(){const rows=[];return{findByPresentationId:id=>rows.filter(x=>x.presentationId===id),findByBindingId:id=>rows.filter(x=>x.bindingId===id),commit:e=>{rows.push(JSON.parse(JSON.stringify(e)));return JSON.parse(JSON.stringify(e));},rows};}
function env(o={}){const p=o.pLedger||ledger(),c=o.cLedger||ledger();const src=o.source||{type:"HUMAN_SOURCE_EVENT",sourceEventRef:"event:1",interactionId:"interaction:1",contentBytesBase64:bytes.toString("base64"),contentEncoding:"utf8",contentMediaType:MEDIA_TYPE};const bind=o.binding||{type:"AUTHENTICATED_HUMAN_SOURCE_EVENT_BINDING",bindingId:"binding:1",sourceEventRef:"event:1",principalRef:"principal:human",contentDigest:sha256(bytes),contentByteLength:bytes.length,contentMediaType:MEDIA_TYPE,originAuthenticationState:"AUTHENTICATED",contentIntegrityState:"EXACT_BYTES",interactionBindingState:"BOUND",authority:"NONE"};return{component:createBootstrapApprovalPresentationCapture({authenticatedBindingPort:()=>bind,sourceEventSnapshotPort:()=>src,presentationLedger:p,captureLedger:c}),pLedger:p,cLedger:c};}
const pres=()=>({rulesetVersion:RULESET_VERSION,presentationId:"presentation:1",interactionId:"interaction:1",payloadBytesBase64:bytes.toString("base64"),payloadMediaType:MEDIA_TYPE});
const cap=()=>({rulesetVersion:RULESET_VERSION,presentationId:"presentation:1",bindingId:"binding:1",sourceEventRef:"event:1"});
const T=[];const test=(n,f)=>T.push([n,f]);
test("exact payload presentation recorded",()=>assert.equal(env().component.present(pres()).outcome,OUTCOMES.PRESENTED));
test("presentation idempotent",()=>{const e=env();e.component.present(pres());assert.equal(e.component.present(pres()).outcome,OUTCOMES.ALREADY_PRESENTED)});
test("presentation identity drift conflicts",()=>{const e=env();e.component.present(pres());const b=Buffer.from("{}","utf8");assert.equal(e.component.present({...pres(),payloadBytesBase64:b.toString("base64")}).outcome,OUTCOMES.CONFLICT)});
test("capture requires presentation evidence",()=>assert.equal(env().component.capture(cap()).outcome,OUTCOMES.UNCERTAIN));
test("exact authenticated response captured",()=>{const e=env();e.component.present(pres());assert.equal(e.component.capture(cap()).outcome,OUTCOMES.CAPTURED)});
test("capture idempotent",()=>{const e=env();e.component.present(pres());e.component.capture(cap());assert.equal(e.component.capture(cap()).outcome,OUTCOMES.ALREADY_CAPTURED)});
test("unauthenticated binding cannot capture",()=>{const e=env({binding:{type:"AUTHENTICATED_HUMAN_SOURCE_EVENT_BINDING",bindingId:"binding:1",sourceEventRef:"event:1",principalRef:"principal:human",contentDigest:sha256(bytes),contentByteLength:bytes.length,contentMediaType:MEDIA_TYPE,originAuthenticationState:"UNKNOWN",contentIntegrityState:"EXACT_BYTES",interactionBindingState:"BOUND",authority:"NONE"}});e.component.present(pres());assert.equal(e.component.capture(cap()).outcome,OUTCOMES.UNCERTAIN)});
test("different response bytes conflict with presentation",()=>{const other=Buffer.from(`${canonicalStringify({...payload,targetPath:"config/other.json"})}\n`);const e=env({source:{type:"HUMAN_SOURCE_EVENT",sourceEventRef:"event:1",interactionId:"interaction:1",contentBytesBase64:other.toString("base64"),contentEncoding:"utf8",contentMediaType:MEDIA_TYPE},binding:{type:"AUTHENTICATED_HUMAN_SOURCE_EVENT_BINDING",bindingId:"binding:1",sourceEventRef:"event:1",principalRef:"principal:human",contentDigest:sha256(other),contentByteLength:other.length,contentMediaType:MEDIA_TYPE,originAuthenticationState:"AUTHENTICATED",contentIntegrityState:"EXACT_BYTES",interactionBindingState:"BOUND",authority:"NONE"}});e.component.present(pres());assert.equal(e.component.capture(cap()).outcome,OUTCOMES.CONFLICT)});
test("different interaction is stale",()=>{const e=env({source:{type:"HUMAN_SOURCE_EVENT",sourceEventRef:"event:1",interactionId:"interaction:2",contentBytesBase64:bytes.toString("base64"),contentEncoding:"utf8",contentMediaType:MEDIA_TYPE}});e.component.present(pres());assert.equal(e.component.capture(cap()).outcome,OUTCOMES.STALE)});
test("caller cannot mark approved",()=>assert.equal(env().component.present({...pres(),approved:true}).outcome,OUTCOMES.REJECTED));
test("presentation creates no authorization",()=>{const r=env().component.present(pres());assert.equal(r.humanAuthorizationCreated,false);assert.equal(r.mutationAuthorized,false)});
test("capture creates no authorization",()=>{const e=env();e.component.present(pres());const r=e.component.capture(cap());assert.equal(r.humanAuthorizationCreated,false);assert.equal(r.mutationAuthorized,false);assert.equal(r.evidence.authority,"NONE")});
let passed=0;for(const[n,f]of T){f();passed++;console.log(`PASS ${n}`)}console.log(`RESULT ${passed}/${T.length} PASS`);
